const http = require('http');
const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');
const crypto = require('crypto');

// Search index entry lifecycle manager
class IndexEntry {
  constructor(docId, content, metadata) {
    this.docId = docId;
    this.content = Buffer.from(content, 'utf-8');
    this.metadata = metadata;
    this.refCount = 1;
    this.freed = false;
    this.allocTime = Date.now();
  }

  acquire() {
    if (this.freed) throw new Error('Use after free');
    this.refCount++;
    return this;
  }

  release() {
    this.refCount--;
    if (this.refCount <= 0) {
      this._deallocate();
    }
  }

  _deallocate() {
    this.content = null;
    this.metadata = null;
    this.freed = true;
  }
}

// Shared index store with reference-counted entries
class SearchIndex {
  constructor() {
    this.entries = new Map();
    this.pendingOps = new Map();
    this.opLog = [];
  }

  addDocument(docId, content, metadata) {
    const entry = new IndexEntry(docId, content, metadata);
    this.entries.set(docId, entry);
    return entry;
  }

  getEntry(docId) {
    const entry = this.entries.get(docId);
    if (entry && !entry.freed) {
      return entry.acquire();
    }
    return null;
  }

  scheduleRemoval(docId, requestId) {
    this.pendingOps.set(requestId, { docId, type: 'remove', timestamp: Date.now() });
  }

  commitRemoval(requestId) {
    const op = this.pendingOps.get(requestId);
    if (!op) return false;
    const entry = this.entries.get(op.docId);
    if (entry) {
      entry.release();
      this.opLog.push({ ...op, committed: Date.now() });
    }
    this.pendingOps.delete(requestId);
    return true;
  }
}

// Reverse proxy request deduplication layer
class ProxyDeduplicator {
  constructor() {
    this.inFlight = new Map();
    this.completionCallbacks = new Map();
  }

  getRequestFingerprint(method, path, body) {
    const hash = crypto.createHash('sha256');
    hash.update(`${method}:${path}:${body || ''}`);
    return hash.digest('hex').substring(0, 16);
  }

  isDuplicate(fingerprint) {
    return this.inFlight.has(fingerprint);
  }

  registerRequest(fingerprint, requestId) {
    if (!this.inFlight.has(fingerprint)) {
      this.inFlight.set(fingerprint, []);
    }
    this.inFlight.get(fingerprint).push(requestId);
  }

  completeRequest(fingerprint) {
    const requestIds = this.inFlight.get(fingerprint) || [];
    this.inFlight.delete(fingerprint);
    return requestIds;
  }
}

// Main service
const index = new SearchIndex();
const dedup = new ProxyDeduplicator();

// Pre-populate some documents
index.addDocument('doc-001', 'Introduction to search indexing', { author: 'admin' });
index.addDocument('doc-002', 'Advanced query optimization', { author: 'admin' });

function handleDeleteRequest(docId, requestId, fingerprint) {
  // Schedule the removal operation
  index.scheduleRemoval(docId, requestId);

  // Register with deduplicator - proxy may retry
  dedup.registerRequest(fingerprint, requestId);

  // Commit the removal
  index.commitRemoval(requestId);

  return { success: true, docId, requestId };
}

function handleProxyRetry(fingerprint, docId) {
  // On proxy retry, we check if original completed
  const completedIds = dedup.completeRequest(fingerprint);

  if (completedIds.length > 0) {
    // Retry detected - but we still commit each pending op
    // This is the "idempotent" retry handler
    const results = completedIds.map(reqId => {
      // Re-commit to ensure consistency (idempotent operation)
      index.commitRemoval(reqId);
      return reqId;
    });
    return { success: true, retried: true, operations: results };
  }
  return { success: false, reason: 'no_pending_operation' };
}

const server = http.createServer((req, res) => {
  let body = '';
  req.on('data', chunk => { body += chunk; });
  req.on('end', () => {
    const url = new URL(req.url, `http://${req.headers.host}`);
    const proxyRequestId = req.headers['x-proxy-request-id'] || crypto.randomUUID();
    const isRetry = req.headers['x-proxy-retry'] === 'true';

    if (req.method === 'DELETE' && url.pathname.startsWith('/index/')) {
      const docId = url.pathname.split('/')[2];
      const fingerprint = dedup.getRequestFingerprint(req.method, url.pathname, body);

      let result;
      if (isRetry) {
        result = handleProxyRetry(fingerprint, docId);
      } else {
        result = handleDeleteRequest(docId, proxyRequestId, fingerprint);
      }

      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(result));
    } else if (req.method === 'GET' && url.pathname.startsWith('/index/')) {
      const docId = url.pathname.split('/')[2];
      try {
        const entry = index.getEntry(docId);
        if (entry) {
          res.writeHead(200, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ docId, content: entry.content?.toString(), metadata: entry.metadata }));
          entry.release();
        } else {
          res.writeHead(404);
          res.end(JSON.stringify({ error: 'not_found' }));
        }
      } catch (e) {
        res.writeHead(500);
        res.end(JSON.stringify({ error: e.message }));
      }
    } else {
      res.writeHead(404);
      res.end(JSON.stringify({ error: 'not_found' }));
    }
  });
});

server.listen(3000, () => console.log('Search index service on :3000'));

